CREATE TABLE "public"."permission" (
  "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" TEXT NOT NULL UNIQUE,
  "description" TEXT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "public"."role_permission" (
  "role_id" INTEGER NOT NULL REFERENCES "public"."role" ("id") ON UPDATE CASCADE,
  "permission_id" INTEGER NOT NULL REFERENCES "public"."permission" ("id") ON UPDATE CASCADE,
  PRIMARY KEY ("role_id", "permission_id")
);

CREATE INDEX "idx_role_permission_role_id" ON "public"."role_permission" ("role_id");

CREATE INDEX "idx_role_permission_permission_id" ON "public"."role_permission" ("permission_id");
